#[Route('/api/shipments', methods: ['POST'])]
public function create(Request $request, EntityManagerInterface $em): JsonResponse
{
    $data = json_decode($request->getContent(), true);
    $order = $em->getRepository(Order::class)->find($data['orderId']);

    $json = file_get_contents(
        'https://api.courier.example/v1/shipments?ref='.$order->getNumber()
    );
    $order->setTrackingCode(json_decode($json, true)['tracking']);
    $em->flush();

    return $this->json(['tracking' => $order->getTrackingCode()]);
}

#[Route('/api/shipments', methods: ['POST'])]
#[IsGranted('ROLE_MERCHANT')]
public function create(
    #[MapRequestPayload] CreateShipment $input,
    OrderRepository $orders,
    ShipmentBooker $booker,
): JsonResponse {
    $order = $orders->find($input->orderId)
        ?? throw $this->createNotFoundException('Order not found');

    $this->denyAccessUnlessGranted('SHIP', $order);

    return $this->json(['tracking' => $booker->book($order)]);
}

final readonly class ShipmentBooker
{
    public function __construct(
        private HttpClientInterface $courierClient,
        private EntityManagerInterface $em,
        private LoggerInterface $logger,
    ) {
    }

    public function book(Order $order): string
    {
        if (null !== $order->getTrackingCode()) {
            return $order->getTrackingCode();   // already booked: don't book again
        }

        try {
            $tracking = $this->courierClient->request('POST', '/v1/shipments', [
                'headers' => ['Idempotency-Key' => 'order-'.$order->getId()],
                'json' => ['reference' => $order->getNumber()],
                'timeout' => 3,
                'max_duration' => 8,
            ])->toArray()['tracking'];
        } catch (ExceptionInterface $e) {
            $this->logger->error('Courier booking failed', [
                'order_id' => $order->getId(), 'exception' => $e,
            ]);

            throw new CourierUnavailableException(previous: $e);
        }

        $order->setTrackingCode($tracking);
        $this->em->flush();

        return $tracking;
    }
}

async function bookShipment(order: Order): Promise<string> {
  if (order.trackingCode) return order.trackingCode // already booked: don't book again

  try {
    const response = await fetch(`${COURIER_URL}/v1/shipments`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Idempotency-Key': `order-${order.id}`,
      },
      body: JSON.stringify({ reference: order.number }),
      signal: AbortSignal.timeout(3000),
    })
    if (!response.ok) throw new Error(`Courier answered ${response.status}`)

    const { tracking } = (await response.json()) as { tracking: string }
    return tracking
  } catch (error) {
    logger.error({ orderId: order.id, err: error }, 'Courier booking failed')
    throw new CourierUnavailableError({ cause: error })
  }
}

